import { esc, cash, icon, pageHead, progress, dateLabel, empty } from './ui.js';
import { getGroupActor, activeGroupMember, canReadGroup, groupApprovers, groupSummary, groupPayoutStatus, groupCollectionStatus, groupMandateReady } from './group-ledger.js';
import { unreadGroupCount } from './group-chat-model.js';
import { openGroupMembers, openGroupDetails, openGroupFinancial, openGroupSimulation, openGroupJoin, openGroupReturn } from './group-actions.js';

const summary = g => groupSummary(g);
const statusName = status => ({pending:'Awaiting approval',approved:'Ready to pay',processing:'Processing',success:'Confirmed',failed:'Failed',cancelled:'Cancelled',declined:'Declined',expired:'Expired'})[status] || status;
const readCount = (ctx,g) => unreadGroupCount(ctx.state,g);
const countLabel = number => number > 99 ? '99+' : number;
const actorName = g => g.members.find(m=>m.id===getGroupActor(g))?.name || 'You';
const actionButton = (label,action,extra='',secondary=false) => `<button type="button" class="button${secondary?' secondary':''}" data-group-action="${action}" ${extra}>${label}</button>`;

export function renderGroupTabs(g,active='overview',unread=0){return `<nav class="group-tabs" aria-label="Group views"><button type="button" data-group-tab="overview"${active==='overview'?' class="selected" aria-current="page"':''}>Overview</button><button type="button" data-group-tab="chat"${active==='chat'?' class="selected" aria-current="page"':''}>Chat${unread?`<span class="group-unread" aria-label="${unread} unread updates">${countLabel(unread)}</span>`:''}</button></nav>`;}

export function renderGroupOverview(ctx,route){
  const g=ctx.state.groups?.find(g=>g.id===route.id);
  if(!g)return `<section class="page life-page">${pageHead('Group money')}${empty({emoji:'◎',title:'Choose your group.',body:'This group is unavailable. Your other groups are still here.',action:'life-groups',label:'Your groups'})}</section>`;
  const actor=getGroupActor(g), member=g.members.find(m=>m.id===actor), allowed=canReadGroup(g), s=summary(g);
  const home=`<button type="button" class="group-home-link" data-group-action="home">${icon('home',16)}<span>Home</span></button>`;
  if(!allowed)return `<section class="page life-page group-overview group-access-page">${pageHead(g.name,{action:home})}<div class="group-access-icon">${icon('users',36)}</div><p class="eyebrow">${member?.status==='invited'?'Invitation waiting':'Group access'}</p><h1 class="large-question">${member?.status==='invited'?`You’re invited,<br>${esc(member.name)}.`:'This group is private.'}</h1><p class="muted">${member?.status==='invited'?'Read the agreement before joining. You’ll be able to see the full earlier group conversation and money history after you accept.':'Only accepted members can open the conversation and group money. Earlier financial records are kept intact.'}</p>${member?.status==='invited'?actionButton('Review invitation','join'):''}${actionButton('Participant simulation','simulation','',true)}<p class="group-local-label">One browser · No live communication</p></section>`;
  const approver=groupApprovers(g).some(m=>m.id===actor), payouts=g.payouts||[], open=payouts.filter(p=>!['success','cancelled','expired','declined'].includes(groupPayoutStatus(p)));
  const pendingContributions=(g.contributions||[]).filter(c=>c.status==='pending');
  const configured=g.members.filter(m=>['approver','creator','owner','admin'].includes(m.role)&&m.status!=='removed').length;
  const canContribute=g.status!=='closed'&&groupCollectionStatus(g)!=='deadline-passed'&&s.remaining>0;
  const returnRefund=g.status==='closed'&&s.balance>0&&g.creatorId===actor;
  const primary=returnRefund?actionButton('Return merchant refund','return-refund'):canContribute?actionButton('Contribute','contribute'):approver&&g.status!=='closed'?actionButton(open.length?'Review payout':'Request payout',open.length?'review':'request',open.length?`data-group-payout="${esc(open[0].id)}"`:''):actionButton('Open chat','chat');
  const secondary=canContribute&&approver&&g.status!=='closed'?actionButton(open.length?'Review payout':'Request payout',open.length?'review':'request',open.length?`data-group-payout="${esc(open[0].id)}"`:'',true):'';
  const past=payouts.filter(p=>!open.includes(p));
  return `<section class="page life-page group-overview" data-group-overview>${pageHead(g.name,{action:home})}${renderGroupTabs(g,'overview',readCount(ctx,g))}<p class="group-sample-label">${g.isSample?'Sample group · Project Printing':'Local group simulation'}</p><div class="group-goal-hero"><p>${g.status==='closed'?'Collection closed':groupCollectionStatus(g)==='deadline-passed'?'Deadline reached':'Collected'}</p><div><strong>${cash(s.collected)}</strong><span>of ${cash(s.target)}</span></div>${progress(s.collected,s.target)}<div class="group-goal-meta"><span>${s.remaining?`${cash(s.remaining)} remaining`:'Target reached ✨'}</span><span>${s.confirmedCount} confirmed${pendingContributions.length?` · ${pendingContributions.length} pending`:''}</span></div></div><div class="inline-actions group-primary-actions">${primary}${secondary}</div>${!groupMandateReady(g)&&g.status!=='closed'?'<button type="button" class="group-pending-note" data-group-action="members"><span>Designated approvers need to accept the payout agreement. Open Your people.</span></button>':''}<div class="panel group-overview-links"><button type="button" class="row" data-group-action="details"><span class="row-icon">${icon('plan',20)}</span><span class="row-copy"><span class="row-title">${esc(g.purpose||g.name)}</span><span class="row-sub">${g.deadline?`By ${esc(dateLabel(g.deadline))} · `:''}${g.status==='closed'?'Closed · Returns recorded':`${s.requiredApprovals} approvals to pay out`}</span></span>${icon('chevron',16)}</button><button type="button" class="row" data-group-action="members"><span class="row-icon">${icon('users',20)}</span><span class="row-copy"><span class="row-title">Your people</span><span class="row-sub">${g.members.filter(m=>!m.status||m.status==='active').length} joined${g.members.some(m=>m.status==='invited')?` · ${g.members.filter(m=>m.status==='invited').length} invited`:''}</span></span>${icon('chevron',16)}</button></div>${s.reserved||s.balance!==s.collected?`<div class="group-account-strip"><span>Group account <strong>${cash(s.balance)}</strong></span>${s.reserved?`<span>${cash(s.reserved)} reserved</span>`:''}</div>`:''}${pendingContributions.length?`<button type="button" class="group-pending-note" data-group-action="simulation">${icon('clock',18)}<span>${cash(pendingContributions.reduce((n,c)=>n+c.amount,0))} processing. This isn’t in the collected total yet.</span>${icon('chevron',15)}</button>`:''}${open.length?`<div class="section-label">Group payouts</div><div class="stack">${open.map(p=>renderPayoutCard(g,p)).join('')}</div>`:''}${past.length?`<details class="group-past-payouts"><summary>Past payouts <span>${past.length}</span>${icon('chevron',15)}</summary><div class="stack">${past.map(p=>renderPayoutCard(g,p)).join('')}</div></details>`:''}<details class="group-contribution-history"><summary>Contributions & agreement ${icon('chevron',15)}</summary><div class="panel">${g.members.filter(m=>m.status!=='removed').map(m=>`<div class="row"><span class="row-icon">${esc(m.name.slice(0,1))}</span><span class="row-copy"><span class="row-title">${esc(m.name)}</span><span class="row-sub">${m.status==='invited'?'Invitation pending':m.id===g.creatorId?'Creator · Approver':m.role==='approver'?'Approver':'Contributor'}</span></span><span class="row-right">${cash(m.amount||0)}</span></div>`).join('')}</div><p class="muted">${s.requiredApprovals} approvals required. ${s.approverCount} active approvers${configured>s.approverCount?` · ${configured-s.approverCount} invited or awaiting agreement`:''}. Each approver reviews the exact payout details.</p></details><p class="group-separation-note">${icon('lock',13)}<span>Group funds stay separate from personal money.</span></p><button type="button" class="group-participant-label" data-group-action="simulation">${icon('users',16)}<span>Participant simulation · ${esc(actorName(g))}</span>${icon('chevron',14)}</button></section>`;
}
function renderPayoutCard(g,p){return `<article class="panel group-payout-card"><div><strong>${cash(p.amount+(p.fee||0))}</strong><span class="group-payout-status ${esc(groupPayoutStatus(p))}">${esc(statusName(groupPayoutStatus(p)))}</span></div><h3>${esc(p.recipient)}</h3>${p.fee?`<p>${cash(p.amount)} to recipient + ${cash(p.fee)} demo fee</p>`:''}<p>${esc(p.note||p.purpose||'Group expense')}</p><div class="group-payout-progress"><span>${p.approvals?.length||0} of ${p.requiredApprovals||summary(g).requiredApprovals} approvals</span>${progress(p.approvals?.length||0,p.requiredApprovals||summary(g).requiredApprovals)}</div>${actionButton(p.status==='success'?'View payment':'Review payout','review',`data-group-payout="${esc(p.id)}"`,true)}</article>`;}

export function bindGroupOverview(ctx,route){
  const root=ctx.$?.('[data-group-overview]')||ctx.$?.('.group-access-page')||document.querySelector('[data-group-overview],.group-access-page');
  if(!root)return()=>{};
  const g=ctx.state.groups?.find(g=>g.id===route.id);if(!g)return()=>{};
  if(g.payouts.some(p=>p.status!=='expired'&&groupPayoutStatus(p)==='expired')){const result=(ctx.actAsync||ctx.act).call(ctx,'expireGroupPayouts',{groupId:g.id});if(result?.then)void result.then(value=>{if(value?.ok)ctx.refresh();});else if(result?.ok)ctx.refresh();}
  let alive=true;const valid=()=>alive&&root.isConnected!==false&&ctx.route?.id===g.id&&ctx.route?.page==='group-detail';
  const click=event=>{const b=event.target?.closest?.('button');if(!b||!valid())return;
    if(b.dataset.groupTab||b.dataset.groupAction==='chat'){ctx.go({section:'life',page:b.dataset.groupTab==='overview'?'group-detail':'group-chat',id:g.id},{replace:!!b.dataset.groupTab});return;}
    const a=b.dataset.groupAction;if(a==='home'){ctx.go({section:'home',page:'home'},{root:true});return;}
    if(a==='simulation'){openGroupSimulation(ctx,g);return;}
    if(a==='join'){openGroupJoin(ctx,g);return;}
    if(!canReadGroup(g))return;
    if(a==='return-refund'){openGroupReturn(ctx,g);return;}
    if(a==='members')openGroupMembers(ctx,g);else if(a==='details')openGroupDetails(ctx,g);else if(['contribute','request','review'].includes(a))openGroupFinancial(ctx,g,a,b.dataset.groupPayout);
  };root.addEventListener('click',click);return()=>{alive=false;root.removeEventListener('click',click);};
}
